using System;
using System.Linq;
using static StrataLint.Scribe.DefinitionDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry.Hyperideal;

internal sealed class FourCycleEnvelopesDocument : IScribeDocumentDefinition
{
    private const string Declaration =
        "D5/S3/Geometry/Hyperideal/FourCycleEnvelopes.cosine_mixed_comparison";
    private static readonly LibraryNoteRef Zhao =
        LibraryNoteRef.Create("D5/L/zhao2026cfmpincidence");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The exact six-variable formula, mixed-coordinate monotonicity and a shared-center inverse-angle application.",
        H("The shared mixed-coordinate comparison"),
        Blocks(
            Paragraph(Text("All variables below are real numbers. Icc(a,b) denotes the closed "
                + "interval [a,b]. In the local edge order (12,13,14,34,24,23), the inputs "
                + "(x,y,z,o,v,w) keep all six coordinates independent. Coordinates x and o "
                + "are opposite.")),
            Paragraph(Text("Define rad(x,y,z)=2xyz+x^2+y^2+z^2-1 and "
                + "P(x,y,z,o,v,w)=yz+vw+xyv+xzw-(x^2-1)o. The function cosine "
                + "is P divided first by sqrt(rad(x,y,w)) and then by sqrt(rad(x,z,v)). "
                + "This is the exact six-variable formula used by the cited source. "
                + "Both radicands are proved positive on the box.")),
            Paragraph(Text("The inverse-angle application uses a different parameter domain from the comparison theorem below. Its six angles have the original order (12,13,14,34,24,23)=(theta,a,b,g,c,d). Set z=cos(theta), D(theta,alpha,beta)=rad(z,cos(alpha),cos(beta)) and I=cosine(z,cos(a),cos(d),cos(g),cos(c),cos(b)). The permutation of the third and sixth inputs retains the original endpoint triples. The comparison theorem on [1,2] is not applied to these cosine inputs.")),
            Paragraph(Text("Assume theta,a,b,c,d>0, theta+a+b<pi and theta+c+d<pi; g may be any real number. Both D(theta,a,b) and D(theta,c,d) are positive. Expanding the existing numerator and using sin(theta)^2=1-z^2 writes I as [sin(theta)^2 cos(g)+cos(a)cos(d)+cos(b)cos(c)+z(cos(a)cos(c)+cos(b)cos(d))]/sqrt(D(theta,a,b)D(theta,c,d)). The same scalar expression occurs in Frigerio-Moraschini, On volumes of truncated tetrahedra with constrained edge lengths, arXiv:1801.05326v3, Section 1.1, formulas (1), (3) and (4), https://arxiv.org/html/1801.05326v3.")),
            Paragraph(Text("For one endpoint split (alpha,beta), put k=cos(alpha+beta), h=cos(alpha-beta), A=z+k, C=cos(alpha)+cos(beta) and E=cos(alpha)-cos(beta). Strict decrease of cosine on [0,pi] gives A>0 from alpha+beta<pi-theta. Sine positivity gives h-k=2sin(alpha)sin(beta)>0, while -1<z<1 and -1<=k<=1. Cosine addition and subtraction and sin^2+cos^2=1 give D=A(z+h), C^2=(1+k)(1+h) and E^2=(1-k)(1-h). Consequently D-A^2=A(h-k)>0, so sqrt(D)>A and D>0.")),
            Paragraph(Text("The squared coordinate gaps factor as (1+k)^2D-A^2C^2=A(1+k)(1-z)(h-k)>=0 and (1-k)^2D-A^2E^2=A(1-k)(1+z)(h-k)>=0. All factors have the indicated signs. Comparing nonnegative squares therefore gives A|C|<=(1+k)sqrt(D) and A|E|<=(1-k)sqrt(D). These estimates use the same z at both endpoints; they do not optimize unrelated endpoint states.")),
            Paragraph(Text("Apply the estimates to (a,b) and (d,c). Write k1=cos(a+b), k2=cos(c+d), A=z+k1, B=z+k2, S=sin(theta)^2 and R=sqrt(D(theta,a,b)D(theta,c,d)). Then R>AB>0 and S>0. Take C1=cos(a)+cos(b), C2=cos(d)+cos(c), E1=cos(a)-cos(b) and E2=cos(d)-cos(c). The numerator N is S cos(g)+(1+z)C1C2/2+(1-z)E1E2/2. In particular, the sign of E2 is fixed by the original six-slot pairing.")),
            Paragraph(Text("Multiplication of the two endpoint bounds and use of the nonnegative weights (1+z)/2 and (1-z)/2 gives AB[N-S cos(g)]<=R[1+k1 k2+z(k1+k2)]=R(AB+S). Since cos(g)<=1 and R>AB with S>0, AB N<=AB S+R(AB+S)<R(AB+2S). Dividing by positive AB and R yields the strict shared-center bound I<1+2sin(theta)^2/[(cos(theta)+cos(a+b))(cos(theta)+cos(c+d))]. This includes obtuse theta and arbitrary g; it assumes no equality of endpoint angles.")),
            Paragraph(Text("The full genuine-angle domain additionally imposes g>0, a+d+g<pi and b+c+g<pi, so it is contained in the scalar domain just used. The trigonometric, product-order and square-root facts combine to give this application of the existing expression. It is distinct from the mixed-coordinate comparison theorem below. Identification of I with cosh of an actual native edge length remains a separate geometric requirement; neither a tetrahedron from angles nor common global lengths, complete face gluing or same-manifold realization follows from this scalar estimate.")),
            Paragraph(Text("An unequal-transverse direct-angle application uses the original six-position vector (r,a,b,o,a,b), with r,a,b,o>1, and assumes all six raw cosine values lie strictly between -1 and 1. Let theta, beta and delta be their principal arccos values at positions 0, 1 and 2. If r>=1+a+b, then pi<2theta+beta+delta. The parameters have no upper bound, a and b need not coincide, and equality in the length threshold is included. The mixed-coordinate comparison on [1,2] is not used for this application.")),
            Paragraph(Text("Put k=a+b, j=a-b, Dr=rad(r,a,b), Do=rad(o,a,b), L=k^2-(r-1)(o-1) and M=(r+1)(o+1)-j^2. At position 0 the raw numerator is N=2ab+r(a^2+b^2)-(r^2-1)o. At positions 1 and 2 the numerators are Na=b(r+o)+a(ro+b^2-a^2+1) and Nb=a(r+o)+b(ro+a^2-b^2+1), with common denominator sqrt(Dr Do). Expanding the original formula gives Dr(1+cos(theta))=(r+1)L and Dr(1-cos(theta))=(r-1)M, so L,M>0. It also gives Dr Do-Na^2=(a^2-1)LM and Dr Do-Nb^2=(b^2-1)LM. Principal angles in (0,pi) have positive sine, hence sin(beta)=sqrt(a^2-1)sqrt(LM)/sqrt(Dr Do) and the analogous identity for delta.")),
            Paragraph(Text("Write S=sqrt(a^2-1)+sqrt(b^2-1), T=(r-1)M/((r+1)L), Q=S^2(r-1)/((r+1)k^2), and F(z)=(z-1)(2(z+1)-j^2)/((z+1)k^2). Positive transverse lengths give S^2>k(k-2) and j^2<(k-2)^2. Since r>=k+1, Q>(k-2)/(k+2). The exact remainder T-F(r)=2(r-1)(o-1)Dr/((r+1)Lk^2) is strictly positive, even when F(r) is negative. Furthermore F(r)-F(k+1)=2(r-k-1)((r+1)(k+2)-j^2)/((r+1)(k+2)k^2)>=0 and F(k+1)>(6-k)/(k+2). Thus T+2Q>1 on the entire stated domain, including r=k+1.")),
            Paragraph(Text("Let eta=(beta+delta)/2 and d=(beta-delta)/2. Principal-angle bounds give 0<eta<pi and |d|<pi/2. The sum-to-product identities, cos(beta)+cos(delta)=kM/sqrt(Dr Do), and the positive-sine formulas give sin(eta)kM=cos(eta)S sqrt(LM). Squaring and using sin(eta)^2+cos(eta)^2=1 yields cos(eta)^2=k^2 M/(k^2 M+S^2 L). The inequality T+2Q>1 implies cos(eta)^2<1-cos(theta). If theta<pi/2, then 0<cos(theta)<1, so cos(eta)^2<sin(theta)^2. Since sin(theta)>0, cos(eta)<sin(theta); this conclusion also covers negative cos(eta). Cosine decreases on [0,pi], giving eta>pi/2-theta. If theta>=pi/2, the positive transverse angles give the desired inequality directly. These two branches establish pi<2theta+beta+delta without an acute-angle premise.")),
            Paragraph(Text("This application concerns the same raw numerator, radicands and actual six-position framing as the existing formula. Identifying its principal angles with those of an actual genuine tetrahedron remains a separate angle-length requirement. It supplies neither a common zero-curvature global length vector, distinct tetrahedra along an actual edge star, a global transverse-angle budget nor a geometric realization of the original manifold. The square-root, rational-order and trigonometric results are reused, and no literature priority is asserted.")),
            Paragraph(Text("The preceding scalar application extends to a conditional demand and capacity argument on actual face-pairing data. Its additional global hypotheses are stated explicitly below. This gives the native analytic application corresponding to the variable-width inference of Sections 96.2 and 96.3: under the dominance, angle-sum and cardinal hypotheses below, the selected blocks demand more transverse angle than the specified actual global edges can carry. The original geometric setting of Sections 95 and 96 requires genuine tetrahedra in the given finite, connected, orientable ideal face-paired manifold, with closed boundary components of genus at least two. The analytic argument here uses the pairing and angle formulas, while the correspondence with that genuine geometric setting remains a separate requirement.")),
            Paragraph(Text("Let T index the blocks and let q be the actual whole-face pairing, with its involution on faces and compatible permutations of their three slots. An actual edge occurrence is a pair (t,j) in T x {0,1,2,3,4,5}, in the original local order (12,13,14,34,24,23). Write E for GlobalEdge(q), the quotient generated by the actual paired-face edge identifications, and P(q,(t,j)) for its quotient map. Thus two distinct local occurrences can represent the same global edge. Choose a finite set I of distinct blocks. The local demand argument needs only this finite selection; for the full global sums and capacity argument, assume T itself is finite. The number |I| counts selected blocks once each, regardless of repeated global labels.")),
            Paragraph(Text("Fix a vertex-induced framing D. For each block t, a permutation of its four vertices induces an edge permutation p_t of the six original positions. The framing specifies actual global edges A_t and B_t in a set H, with A_t != B_t, and the four equations P(q,(t,p_t(1)))=P(q,(t,p_t(4)))=A_t and P(q,(t,p_t(2)))=P(q,(t,p_t(5)))=B_t. These are equalities in the actual quotient, not a choice of colors on a diagram. The labels A_t and B_t may change with t, and labels may recur in different blocks. No further distinctness is required for the two axial labels at positions 0 and 3; they may coincide with each other or with transverse labels whenever the other stated premises allow it.")),
            Paragraph(Text("Fix one vector x:E -> R with x(e)>1 for every actual global edge e. All local values and every angle equation in this application use this same x. Define v_t(j)=x(P(q,(t,j))) in original coordinates and w_t(j)=v_t(p_t(j)) in the chosen frame. Assume that x(P(q,(t,p_t(0))))=r for every t in I. With a_t=x(A_t), b_t=x(B_t) and o_t=x(P(q,(t,p_t(3)))), the four slot equations give w_t=(r,a_t,b_t,o_t,a_t,b_t) on I. Each a_t,b_t,o_t is greater than 1. The common axial value r is also greater than 1 once I is nonempty. Equality of axial numerical values is all that is imposed here; it does not assert that all axial occurrences represent a single edge. Distinct labels A_t and B_t may have equal values a_t=b_t, and both values may vary across blocks.")),
            Paragraph(Text("At an original occurrence (t,j), put alpha_x(t,j)=TwoLengthAngleSum.extendedAngle(v_t,j)=arccos(max(-1,min(rawCos(v_t,j),1))). This is the original extended-angle function evaluated at the actual local vector. On every selected block assume the strict raw-interior conditions -1<rawCos(w_t,j)<1 for all six positions j, and set theta_t=arccos(rawCos(w_t,0)), beta_t=arccos(rawCos(w_t,1)) and delta_t=arccos(rawCos(w_t,2)). These principal angles lie in (0,pi). The strict conditions are imposed on all six raw values, even though the local demand conclusion displays only three angles; they are not asserted to characterize the genuine-tetrahedron domain.")),
            Paragraph(Text("The vertex-induced frame preserves the original angle formula. More precisely, positivity of all coordinates gives positive radicands, and the numerator and the product of the two radicands transform under a vertex permutation to the corresponding original edge expressions. The two radicands can interchange, without changing their positive square-root product. Hence rawCos(w_t,j)=rawCos(v_t,p_t(j)), and the same identity holds for extendedAngle. On selected blocks the strict raw-interior conditions remove the clipping, so arccos(rawCos(w_t,j))=alpha_x(t,p_t(j)) for every j. This supplies the principal-to-actual angle identification used in the sums; it does not identify these analytic angles with geometric dihedral angles.")),
            Paragraph(Text("The half-circle input is the actual occurrence equation sum over t in I of alpha_x(t,p_t(0))=pi. It is an explicit hypothesis. A vertex frame, common axial value, or face pairing alone does not produce this equation or exhibit I as an actual geometric edge star. It also supplies the needed nonemptiness: if I were empty, the left side would be zero, contradicting pi>0. Choosing a block in I now gives r>1 from x>1 and the common axial equation. By angle transport the half-circle input is exactly sum over t in I of theta_t=pi. No nonemptiness or lower cardinality premise is added for the demand step.")),
            Paragraph(Text("First impose axial dominance r>=1+a_t+b_t for every selected block. The scalar application above applies separately to the vector (r,a_t,b_t,o_t,a_t,b_t) of each block and yields pi<2theta_t+beta_t+delta_t. Its hypotheses have all been supplied by x>1, the paired slot equations and strict raw-interiority. Equality in the dominance threshold is allowed, and the conclusion remains strict. Neither theta_t<pi/2 nor constancy of the transverse values is required. In particular, the summation does not compare blocks through a common response parameter or use a same-parameter Jensen inequality.")),
            Paragraph(Text("Summing these strict inequalities over the nonempty finite set I gives |I| pi < 2 sum over I of theta_t + sum over I of (beta_t+delta_t) = 2pi + sum over I of (beta_t+delta_t). Subtracting 2pi and multiplying by the positive number 2 gives the exact strict demand bound 2(|I|-2)pi < 2 sum over I of (beta_t+delta_t). Here |I| is viewed as a real number before subtracting 2; the expression is real subtraction, not truncated natural-number subtraction. The demand bound has used neither a global transverse budget nor a count of edges in that budget.")),
            Paragraph(Text("For capacity, choose a finite set U of actual global edges such that A_t and B_t both belong to U for every t in I. This is a separate condition on the selected blocks; no equality or inclusion between U and the framing's set H is required. Assume the full original global equations for the same vector x: for every e in E, the sum over all occurrences (t,j) in T x {0,1,2,3,4,5} of alpha_x(t,j) when P(q,(t,j))=e, and zero otherwise, equals 2pi. These are explicit premises on all original occurrence coordinates. They are not inferred from the local scalar inequality, and they are not replaced by equations only on the selected transverse slots or by unrelated local angle assignments.")),
            Paragraph(Text("To identify the slots whose demand is being counted, let s(0)=1, s(1)=2, s(2)=4 and s(3)=5, and map (t,k) in I x {0,1,2,3} to J(t,k)=(t,p_t(s(k))). This map is injective on actual occurrences: equality of two images first gives equality of their block indices; injectivity of that block's edge permutation then gives s(k)=s(l), and the four distinct listed positions give k=l. Let V be its image. This constructs the four distinct occurrences from each distinct selected block. It does not assume an injection into E. The two A_t occurrences and the two B_t occurrences remain distinct members of V even though their quotient labels repeat, and occurrences in different blocks remain distinct even when their labels coincide.")),
            Paragraph(Text("For each e in U, form the full fiber F_e={(t,j) in T x {0,1,2,3,4,5}: P(q,(t,j))=e}, and let W_U be the union of all these fibers. The fibers are pairwise disjoint: an occurrence in both F_e and F_f would have the single quotient value P(q,(t,j)) equal to both e and f, forcing e=f. They partition precisely all actual occurrences whose global labels belong to U. In particular, W_U includes occurrences outside I and any axial occurrences carrying labels in U, as well as the selected transverse occurrences. Repeated occurrences of an edge are retained inside its fiber, and each occurrence in W_U belongs to exactly one fiber.")),
            Paragraph(Text("The original all-edge equations identify the sum of alpha_x on each F_e with 2pi. Summing over the disjoint fibers therefore gives sum over W_U of alpha_x = sum over e in U of sum over F_e of alpha_x = 2|U|pi. The four framing equations and membership of A_t,B_t in U imply V is a subset of W_U. Every original extended angle is nonnegative, since it is a principal arccos value, including at unselected blocks where strict raw-interiority has not been assumed. Thus sum over V of alpha_x <= sum over W_U of alpha_x = 2|U|pi. This derives capacity from the full original equations and nonnegativity; it introduces no independent budget hypothesis and requires no strict-interior condition outside I.")),
            Paragraph(Text("The sum on V is exactly the transverse expression in the demand bound. Injectivity of J rewrites it as the sum over t in I of alpha_x(t,p_t(1))+alpha_x(t,p_t(2))+alpha_x(t,p_t(4))+alpha_x(t,p_t(5)). Frame transport identifies these with the four framed principal angles. In the original raw formula evaluated at (r,a_t,b_t,o_t,a_t,b_t), positions 4 and 1 have identical expressions, and positions 5 and 2 have identical expressions. Their principal angles are consequently equal within each block. The four contributions are beta_t, delta_t, beta_t, delta_t, and hence sum over V of alpha_x = 2 sum over I of (beta_t+delta_t). This equality is derived from transport and the paired formula, without imposing any equality of angles between different blocks.")),
            Paragraph(Text("Combining the derived demand and capacity under dominance yields 2(|I|-2)pi < 2 sum over I of (beta_t+delta_t) <= 2|U|pi. Now impose the source's cardinal threshold |U|+2<=|I|. Casting this natural-number comparison to the reals gives |U|<=|I|-2; multiplication by 2pi>0 gives 2|U|pi<=2(|I|-2)pi, contradicting the strict chain. The threshold is a stated conditional premise. There is no additional occurrence-count, angle-budget or injectivity assumption: the occurrence injection, full-fiber budget and image-angle identity were derived above. In the source notation, g=|I| and the number of transverse global edges is |U|; the letter q here denotes the actual pairing.")),
            Paragraph(Text("Finally keep the pairing, framing, single vector x>1, common axial value, all-six strict raw-interior conditions on I, actual half-circle equation, transverse membership in U, full original all-edge equations and |U|+2<=|I|, but remove dominance from the hypotheses. If no t in I satisfied r-1<a_t+b_t, real linear order would give a_t+b_t<=r-1 for every selected block, equivalently r>=1+a_t+b_t throughout I. That would restore the dominance assumptions and the contradiction just obtained. Consequently there is a selected block t with r-1<a_t+b_t. The escape conclusion has no dominance premise; it states precisely where universal dominance must fail under the remaining conditions.")),
            Paragraph(Text("This application advances the native analytic conditional inference by supplying its explicit occurrence accounting and global capacity derivation. The earlier scalar-only limitation concerns that local application; the capacity argument here expressly assumes the full global equations and does not construct a solution of them. To recover the original geometric conclusion one still needs the correspondence between raw-interior data and genuine tetrahedra, between native angles and geometric angles, and between x(e) and cosh of compatible positive edge lengths. Existence of one global metric vector, complete face gluing and realization of the given manifold, including its connectivity, orientability and boundary requirements, remain separate geometric obligations. So does obtaining the selected distinct blocks and their half-circle equation from an actual edge star. The width escape does not construct a closed width-growth cycle, and this conditional analytic application does not complete the geometric argument or the full CFMP 1-125 objective.")),
            Describe.Lean(
                DescribeId.Create("hyperideal-mixed-coordinate-comparison"),
                DeclarationHandle.Create(Declaration),
                H("Increasing neighbours and decreasing the opposite coordinate"),
                StatementSource.FromAuthor(F.Disp(Statement())),
                AssessedProvenance.FromLiterature(Zhao),
                Blocks(
                    Paragraph(Text("All eleven variables lie in [1,2]. Increasing the four "
                        + "neighbouring coordinates and decreasing the opposite coordinate cannot "
                        + "decrease the actual cosine. The proof differentiates the original "
                        + "square-root expression and derives the nonnegative coupled numerator "
                        + "(x^2-1)(xow+xv+yo+yvw+z(1-w^2)). It retains endpoint continuity, "
                        + "positive denominators and the two actual tetrahedral symmetries.")),
                    Paragraph(Text("Endpoint envelopes used by later incidence arguments are "
                        + "obtained there by direct specialization and normalization. They are "
                        + "not separate formal declarations. Geometric identification with a "
                        + "tetrahedron, face-pairing topology and the global co-volume existence "
                        + "argument remain outside this analytic theorem."))),
                DescribeRole.Theorem))));

    private static Formula Statement()
    {
        string[] names = ["x", "y", "z", "o", "v", "w", "Y", "Z", "O", "V", "W"];
        var a = names.Select(F.Id).ToArray();
        var intervals = a.Select(t => In(t, F.D(1), F.D(2))).ToArray();
        Formula[] orders = [Le(a[1], a[6]), Le(a[2], a[7]), Le(a[8], a[3]),
            Le(a[4], a[9]), Le(a[5], a[10])];
        return ForAll(names, Implies(And([.. intervals, .. orders]),
            Le(Call("cosine", a[0], a[1], a[2], a[3], a[4], a[5]),
               Call("cosine", a[0], a[6], a[7], a[8], a[9], a[10]))));
    }

    private static Formula ForAll(string[] names, Formula body)
    {
        var real = new Formula.NamedConstant(FormulaIdentifier.Create("Real"));
        Formula.BoundVariable[] binders = names.Select(name =>
            new Formula.BoundVariable(FormulaIdentifier.Create(name), real)).ToArray();
        return new Formula.BindMany(FormulaQuantifier.ForAll, [.. binders], body);
    }

    private static Formula And(params Formula[] clauses)
    {
        if (clauses.Length == 0) throw new ArgumentException("Empty conjunction.");
        var result = clauses[^1];
        for (var i = clauses.Length - 2; i >= 0; i--)
            result = new Formula.Logic(clauses[i], FormulaLogicOperator.And, result);
        return result;
    }

    private static Formula Implies(Formula premise, Formula conclusion) =>
        new Formula.Logic(premise, FormulaLogicOperator.Implies, conclusion);
    private static Formula Le(Formula left, Formula right) =>
        new Formula.Relation(left, FormulaRelationOperator.LessThanOrEqual, right);
    private static Formula In(Formula value, Formula lower, Formula upper) =>
        new Formula.Relation(value, FormulaRelationOperator.MemberOf, Call("Icc", lower, upper));
    private static Formula Call(string name, params Formula[] args) =>
        new Formula.Apply(F.Id(name), [.. args]);
}
